		private global::System.Collections.IEnumerator CreatePokeForFureaiEnter(uint SelectPoke_TemotiNo) {
            var pokePara = PlayerWork.playerParty.GetMemberPointer(SelectPoke_TemotiNo);
            Dpr.Field.Walking.WalkingCharacterModel mod = null;

            global::UnityEngine.Vector2Int[] posArray;
            int initX;
            if (EntityManager.activeFieldPlayer.worldPosition.x <= -45.0f)
            {
                posArray = EnterPosArrayRight;
                initX = 51;
            }
            else
            {
                posArray = EnterPosArrayLeft;
                initX = 12;
            }

            AddPokeCor = pokeFactory.AddPoke(pokePara, model =>
            {
                model.controller.OnPlayerNear += pokeWalkMng.AddPoke;
                model.OnWarp = pokeWalkMng.OnWarp;
                AddPokeCor = null;
                model.CreateWarpEffect();
                mod = model;
                model.GetEntity().SetYawAngleDirect(180.0f);
                model.isSelectPoke = true;
                model.AI.ChangeState(typeof(WaitState));
            }, true, new Vector2Int(initX, 47));
            yield return Sequencer.Start(AddPokeCor);

            pokeFactory.PokeList.ForEach(x => x.controller.getWalkingCharacters = pokeWalkMng.GetPokeWalkers);
            firstMod = (FureaiPokeModel)mod;
            yield return new WaitForEndOfFrame();

            AudioManager.Instance.PlaySe(AK.EVENTS.PLAY_BA_SYS_POKE_APPERANCE_FIELD, null);
            mod.CreateWarpEffect();

            uint num = PlayerWork.playerParty.GetMemberCount();
            Coroutine cor = Sequencer.Start(new MyWaitForSeconds(0.6f));
            int enablePokeNum = 1;

            for (uint i = 0; i < num; i++)
            {
                var p = PlayerWork.playerParty.GetMemberPointer(i);
                if (IsEnterble((int)p.GetMonsNo()) && !p.IsEgg(EggCheckType.BOTH_EGG))
                    yield return FureaiDataManager.LoadPokeAsset(p.GetMonsNo(), fureaiDataManager.PokeAssets, p.GetFormNo(), p.GetSex(), p.IsRare(), 1);
            }

            yield return cor;

            int count = 0;
            for (int i = 0; i < num; i++)
            {
                if (i == SelectPoke_TemotiNo)
                    continue;

                var p = PlayerWork.playerParty.GetMemberPointer((uint)i);
                if (!IsEnterble((int)p.GetMonsNo()) || p.IsEgg(EggCheckType.BOTH_EGG))
                    continue;

                enablePokeNum++;
                AddPokeCor = pokeFactory.AddPoke(p, model =>
                {
                    model.controller.OnPlayerNear += pokeWalkMng.AddPoke;
                    model.OnWarp = pokeWalkMng.OnWarp;
                    AddPokeCor = null;
                    mod = model;
                    model.isSelectPoke = false;
                }, true, posArray[count]);
                count++;

                cor = Sequencer.Start(new MyWaitForSeconds(0.3f));
                yield return Sequencer.Start(AddPokeCor);

                yield return new WaitForEndOfFrame();

                AudioManager.Instance.PlaySe(AK.EVENTS.PLAY_BA_SYS_POKE_APPERANCE_FIELD, null);
                if (mod != null)
                    mod.CreateWarpEffect();

                yield return cor;
            }

            isInHiroba = true;
            isCreatingPoke = false;

            pokeFactory.PokeList.ForEach(x =>
            {
                x.GetWalkers = () => pokeFactory.PokeList.Select(walker => walker.walkData.entity).ToArray();
                x.GetHirobaPokes = () => pokeFactory.PokeList;
            });

            if (enablePokeNum == 1)
                AddFirstPoke();
        }
		public void HirobaEnterKaisan() {
            isKaisanPoke = true;

            var list = pokeFactory.PokeList.FindAll(x => x.nowState == typeof(WaitState));
            pokeFactory.CreatePositionNoList(list.Count);
            var randomList = list.OrderBy(i => Guid.NewGuid()).ToList();

            Sequencer.Start(RouteCheck(randomList));
        }
		public void HirobaExitSyuugou() {
            isSyuugouPoke = true;
            isInHiroba = false;

            ToCameraDefault(1.0f).OnComplete(() => { });

            bool isPlayerLeftEntrance = EntityManager.activeFieldPlayer.worldPosition.x > -45.0f;
            int count = 0;

            pokeFactory.PokeList.ForEach(x =>
            {
                if (Vector3.Distance(x.walkData.entity.transform.position, EntityManager.activeFieldPlayer.worldPosition) > 20.0f)
                {
                    count++;
                    if (isPlayerLeftEntrance)
                        x.Warp(new Vector3(-10 - count * 2, 0.0f, 34.0f), true);
                    else
                        x.Warp(new Vector3(count * -1.5f - 43.5f, 0.0f, 35.0f), true);
                }

                DOVirtual.DelayedCall(0.2f, () =>
                {
                    ((FureaiExitState)x.AI.ChangeState(typeof(FureaiExitState))).OnPlayerNear = () =>
                    {
                        Sequencer.Start(DoEndofFrame(() =>
                        {
                            AudioManager.Instance.PlaySe(AK.EVENTS.PLAY_BA_SYS_BALL_OPEN_FIELD, null);
                            x.CreateWarpEffect();
                            DelPoke(x);

                            if (pokeFactory.PokeList.Count == 0)
                                isSyuugouPoke = false;
                        }));
                    };
                });
            });
        }
		private global::System.Collections.IEnumerator DoEndofFrame(global::System.Action act) {
            yield return new WaitForEndOfFrame();
            act();
        }
		private global::System.Collections.IEnumerator RouteCheck(global::System.Collections.Generic.List<global::Dpr.FureaiHiroba.FureaiPokeModel> list) {
            for (int i = 0; i < list.Count; i++)
            {
                pokeFactory.SetPokePosition(false, null, list[i], default(Vector2Int));
                pokeFactory.SetPairModel(list[i]);
                list[i].CreateRoute(list[i].sanpoModel.InitPos, 60);

                yield return new WaitForEndOfFrame();

                list[i].AI.ChangeState(typeof(GotoSanpoState));
                list[i].AI.GetNowState().Play(new LookAtNextRoute(UnityEngine.Random.Range(2.5f, 3.0f), UnityEngine.Random.Range(0.8f, 1.0f)), null);
            }

            yield return new MyWaitForSeconds(2.0f);

            isKaisanPoke = false;
            isEntering = false;
            AddFirstPoke();
        }
		private void AddFirstPoke() {
            pokeWalkMng.AddPoke(firstMod);
            firstMod = null;
        }
		public void SetSelectWalkingPoke(uint temotiNo) {
            var select = pokeFactory.PokeList.Find(x => x.isSelectPoke);
            if (select != null)
                select.isSelectPoke = false;

            pokeFactory.PokeList.Find(x => x.TemotiNo == temotiNo).isSelectPoke = true;
        }
		public int GetSelectWalkingPokeTemotiNo() {
            return (int)pokeFactory.PokeList.Find(x => x.isSelectPoke).TemotiNo;
        }
		public void SelectPokeHide() {
            pokeFactory.PokeList.Find(x => x.isSelectPoke).entity.transform.localScale = Vector3.zero;
        }
		public void SelectPokeGotoPlayerNear() {
            FureaiPokeModel selectPoke = pokeFactory.PokeList.Find(x => x.isSelectPoke);
            selectPoke.AI.GetNowState().Cancel();
            selectPoke.AI.ChangeState(typeof(WaitState));
            AICommon.WarpImmidiate(selectPoke.AI.aiModel, true);

            var player = EntityManager.activeFieldPlayer;
            var diff = selectPoke.walkData.entity.transform.position - player.worldPosition;
            player.SetYawAngleDirect(Utils.Vector2ToAngle(new Vector2(diff.x, diff.z), 0.0f));

            int Rank = Utils.GetNakayoshiRank(selectPoke.nakayoshi);
            int motionID = Utils.GetNakayoshiRankMotion(Rank);

            selectPoke.AI.GetNowState().Play(new LookAtPlayer(0.5f, 5.0f), () =>
            {
                selectPoke.AI.GetNowState().PlayAnim(motionID, () => pokeWalkMng.AddPoke(selectPoke));

                if (Utils.IsPikaV(selectPoke.monsNo))
                    Utils.PlayVoicePikaBui_NakayoshiRank(selectPoke.monsNo, Rank, selectPoke.controller.voicePlayer);
                else
                    Utils.PlayVoice(selectPoke.monsNo, selectPoke.GetPokeParam().GetFormNo(), 0, selectPoke.controller.voicePlayer);
            });
        }
		public void TalkStart(int temoti) {
            var poke = pokeFactory.PokeList.Find(x => x.GetPokeParam() == PlayerWork.playerParty.GetMemberPointer((uint)temoti));
            if (poke.isWarping)
                return;

            poke.isForceAnimation = true;
            Sequencer.Start(WaitEventEnd(poke));
        }
		private global::System.Collections.IEnumerator WaitEventEnd(global::Dpr.FureaiHiroba.FureaiPokeModel poke) {
            while (poke.entity.EventParams.IsEventRunning)
                yield return null;

            poke.isForceAnimation = false;
            poke.controller.emoticon.Delete();
        }
		public void PlayVoice_TemotiID(uint temoti) {
            var poke = pokeFactory.PokeList.Find(x => x.GetPokeParam() == PlayerWork.playerParty.GetMemberPointer(temoti));
            var monsNo = poke.monsNo;
            int rank = Utils.GetNakayoshiRank(poke.GetPokeParam().GetFriendship());

            if (Utils.IsPikaV(monsNo))
                Utils.PlayVoicePikaBui_NakayoshiRank(monsNo, rank, poke.controller.voicePlayer);
            else
                Utils.PlayVoice(poke.monsNo, poke.GetPokeParam().GetFormNo(), 0, poke.controller.voicePlayer);
        }
		public global::System.Collections.Generic.List<global::Dpr.FureaiHiroba.FureaiPokeModel> GetWalkingPokes() {
            return pokeWalkMng.GetPokeWalkers();
        }
		private void OnDestroy() {
            Sequencer.update -= MyUpdate;
            Sequencer.lateUpdate -= MyLateUpdate;

            // Plain reference test (cbz @01a83a4c), not the UnityEngine.Object operator.
            UIManager.Instance?.UnloadWindows(new List<UIWindowID>() { UIWindowID.FUREAI_POKESELECT });

            pokeWalkMng.GetPokeWalkers().ForEach(x => x.controller.OnPlayerNear -= pokeWalkMng.AddPoke);

            fureaiPokeModels.Clear();
            fureaiPokeModels = null;

            _EnterHirobaCreate = null;
            _EnterHirobaKaisan = null;
            _ExitHirobaSyuugou = null;

            fureaiDataManager.Destroy();
            fureaiDataManager = null;
            pokeWalkMng = null;
            pokeFactory = null;

            if (FieldManager.abUnloader != null)
            {
                FieldManager.abUnloader.Unload(1);
                FieldManager.abUnloader.Unload(0);
            }
        }
